* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: #f6f8fc;
  color: #111827;
}

.planning-shell {
  min-height: 100%;
  padding: 18px;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.08), transparent 36%), linear-gradient(315deg, rgba(16, 185, 129, 0.08), transparent 32%), #f6f8fc;
}

.planning-top {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 16px;
}

.planning-title h1 {
  margin: 0;
  font-size: 24px;
  font-weight: 850;
}

.planning-title p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
}

.planning-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.planning-filters select,
.planning-filters input {
  height: 38px;
  border: 1px solid #d8dee9;
  background: #fff;
  border-radius: 8px;
  padding: 0 10px;
  min-width: 135px;
  color: #111827;
}

.planning-filters button {
  height: 38px;
  border: 0;
  border-radius: 8px;
  padding: 0 14px;
  font-weight: 800;
  cursor: pointer;
}

.btn-primary {
  background: #2563eb;
  color: #fff;
}

.btn-light {
  background: #e8eef8;
  color: #1f2937;
}

.kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(145px, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.kpi-card,
.panel {
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid #e5e9f2;
  border-radius: 10px;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.06);
}

.kpi-card {
  padding: 14px;
}

.kpi-label {
  font-size: 12px;
  color: #64748b;
  font-weight: 800;
  text-transform: uppercase;
}

.kpi-value {
  margin-top: 7px;
  font-size: 25px;
  font-weight: 850;
}

.kpi-sub {
  margin-top: 6px;
  font-size: 12px;
  color: #64748b;
}

.delta-up {
  color: #059669;
  font-weight: 850;
}

.delta-down {
  color: #dc2626;
  font-weight: 850;
}

.main-grid {
  display: grid;
  grid-template-columns: 1.45fr 0.75fr;
  gap: 12px;
}

.panel {
  padding: 14px;
}

.panel h2 {
  margin: 0 0 12px;
  font-size: 15px;
}

.chart-wrap {
  height: 280px;
}

.chart-empty {
  height: 220px;
  display: grid;
  place-items: center;
  color: #94a3b8;
  border: 1px dashed #dbe3ef;
  border-radius: 10px;
}

.legend {
  display: flex;
  gap: 14px;
  margin-top: 10px;
  color: #64748b;
  font-size: 12px;
}

.legend span::before {
  content: "";
  display: inline-block;
  width: 18px;
  height: 3px;
  border-radius: 10px;
  margin-right: 6px;
  vertical-align: middle;
}

.legend .actual::before {
  background: #2563eb;
}

.legend .target::before {
  background: #10b981;
}

.progress-card {
  display: grid;
  place-items: center;
  padding: 12px 0;
}

.ring {
  width: 170px;
  height: 170px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: conic-gradient(#2563eb var(--pct), #e5eaf2 0);
}

.ring-inner {
  width: 125px;
  height: 125px;
  border-radius: 50%;
  background: #fff;
  display: grid;
  place-items: center;
  text-align: center;
}

.ring-inner strong {
  font-size: 30px;
}

.metric-list {
  margin-top: 14px;
  display: grid;
  gap: 8px;
}

.metric-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid #eef2f7;
  padding-top: 8px;
  font-size: 13px;
}

.metric-row span {
  color: #64748b;
}

.trend-table {
  width: 100%;
  margin-top: 14px;
  border-collapse: collapse;
  font-size: 12px;
}

.trend-table th,
.trend-table td {
  padding: 9px 8px;
  border-bottom: 1px solid #edf1f7;
  text-align: right;
}

.trend-table th:first-child,
.trend-table td:first-child {
  text-align: left;
}

.trend-table th {
  color: #64748b;
  font-weight: 800;
  background: #f8fafc;
}

.branch-panel {
  margin-top: 12px;
}

.branch-list {
  display: grid;
  gap: 10px;
}

.branch-row {
  border: 1px solid #e8edf5;
  background: #fbfdff;
  border-radius: 10px;
  padding: 12px;
}

.branch-main {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 13px;
}

.branch-main span {
  color: #64748b;
  font-weight: 800;
}

.branch-bar {
  height: 8px;
  background: #e7edf6;
  border-radius: 999px;
  overflow: hidden;
  margin: 10px 0;
}

.branch-bar div {
  height: 100%;
  background: linear-gradient(90deg, #2563eb, #10b981);
}

.branch-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(115px, 1fr));
  gap: 8px;
  font-size: 12px;
  color: #64748b;
}

.branch-metrics strong {
  color: #111827;
}

@media print {
  body, .planning-shell {
    background: #fff;
  }
  .planning-shell {
    padding: 0;
  }
  .planning-filters {
    display: none;
  }
  .panel, .kpi-card {
    box-shadow: none;
    break-inside: avoid;
  }
}

