const root = document.getElementById("planning-dashboard");

function n(value) {
  return Number(value || 0);
}

function money(value) {
  return n(value).toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function qty(value) {
  return n(value).toLocaleString("en-US", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 2
  });
}

function pct(value) {
  return Math.max(0, Math.min(999, n(value))).toFixed(1);
}

function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, char => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;"
  })[char]);
}

function pick(obj, keys, fallback = 0) {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null) return obj[key];
  }
  return fallback;
}

function delta(current, previous) {
  if (!n(previous)) return { text: "New period", cls: "delta-up" };

  const value = ((n(current) - n(previous)) / Math.abs(n(previous))) * 100;

  return {
    text: `${value >= 0 ? "+" : ""}${value.toFixed(1)}% vs previous`,
    cls: value >= 0 ? "delta-up" : "delta-down"
  };
}

function chartSvg(rows) {
  const data = rows || [];

  if (!data.length) {
    return `<div class="chart-empty">No trend data for selected period.</div>`;
  }

  const width = 760;
  const height = 260;
  const pad = 32;

  const actual = data.map(row => n(row.actualSales));
  const target = data.map(row => n(row.salesTarget));
  const maxValue = Math.max(...actual, ...target, 1);

  const x = index => pad + (index * (width - pad * 2)) / Math.max(data.length - 1, 1);
  const y = value => height - pad - (n(value) / maxValue) * (height - pad * 2);

  const path = values => values.map((value, index) =>
    `${index === 0 ? "M" : "L"} ${x(index).toFixed(1)} ${y(value).toFixed(1)}`
  ).join(" ");

  const dots = actual.map((value, index) =>
    `<circle cx="${x(index).toFixed(1)}" cy="${y(value).toFixed(1)}" r="4" fill="#2563eb" />`
  ).join("");

  const labels = data.map((row, index) => {
    if (data.length > 12 && index % Math.ceil(data.length / 8) !== 0) return "";
    return `<text x="${x(index).toFixed(1)}" y="${height - 8}" text-anchor="middle" font-size="10" fill="#64748b">${esc(row.label || row.targetDate || "")}</text>`;
  }).join("");

  return `
    <svg viewBox="0 0 ${width} ${height}" width="100%" height="100%" preserveAspectRatio="none">
      <line x1="${pad}" y1="${height - pad}" x2="${width - pad}" y2="${height - pad}" stroke="#e5eaf2" />
      <line x1="${pad}" y1="${pad}" x2="${pad}" y2="${height - pad}" stroke="#e5eaf2" />
      <path d="${path(target)}" fill="none" stroke="#10b981" stroke-width="3" stroke-dasharray="7 6" />
      <path d="${path(actual)}" fill="none" stroke="#2563eb" stroke-width="4" />
      ${dots}
      ${labels}
    </svg>
  `;
}

function branchOptions(branches, selectedBranchId, canChangeBranch) {
  const all = canChangeBranch
    ? `<option value="0"${String(selectedBranchId) === "0" ? " selected" : ""}>All branches</option>`
    : "";

  return all + (branches || []).map(branch => {
    const value = String(branch.value || branch.branchId || branch.id || "");
    const label = branch.label || branch.name || branch.branchName || value;

    return `<option value="${esc(value)}"${value === String(selectedBranchId) ? " selected" : ""}>${esc(label)}</option>`;
  }).join("");
}

function branchPerformancePanel(rows = []) {
  if (!rows.length) {
    return `
      <div class="panel branch-panel">
        <h2>Branch Performance</h2>
        <div class="chart-empty">No branch performance data for selected period.</div>
      </div>
    `;
  }

  return `
    <div class="panel branch-panel">
      <h2>Branch Performance</h2>

      <div class="branch-list">
        ${rows.map(row => {
          const achievement = n(row.achievementPct);
          const change = n(row.previousChangePct);
          const gap = n(row.salesGap);

          return `
            <div class="branch-row">
              <div class="branch-main">
                <strong>${esc(row.branchCode || "")} · ${esc(row.branchName || "")}</strong>
                <span>${money(row.actualSales)} / ${money(row.salesTarget)}</span>
              </div>

              <div class="branch-bar">
                <div style="width:${Math.min(achievement, 100)}%"></div>
              </div>

              <div class="branch-metrics">
                <span>Achievement <strong>${pct(achievement)}%</strong></span>
                <span>Gap <strong>${money(gap)}</strong></span>
                <span>Avg basket <strong>${money(row.averageBasket)}</strong></span>
                <span class="${change >= 0 ? "delta-up" : "delta-down"}">
                  ${change >= 0 ? "+" : ""}${change.toFixed(1)}%
                </span>
              </div>
            </div>
          `;
        }).join("")}
      </div>
    </div>
  `;
}

function render() {
  const model = appsmith.model || {};
  const summary = model.summary || {};
  const previous = model.previousSummary || {};
  const trend = model.dailyTrend || [];

  const salesTarget = pick(summary, ["salesTarget", "targetSales", "plannedSales"]);
  const actualSales = pick(summary, ["actualSales", "salesAmount", "totalSales"]);
  const salesPct = pick(
    summary,
    ["salesAchievementPct", "achievementPct"],
    salesTarget ? actualSales / salesTarget * 100 : 0
  );

  const transactionTarget = pick(summary, ["transactionTarget", "targetTransactions"]);
  const actualTransactions = pick(summary, ["actualTransactions", "transactionCount"]);
  const itemTarget = pick(summary, ["itemQtyTarget", "targetItemQty"]);
  const actualItems = pick(summary, ["actualItemQty", "itemQty"]);
  const avgBasket = actualTransactions ? actualSales / actualTransactions : 0;

  const salesDelta = delta(actualSales, previous.previousSales);
  const txDelta = delta(actualTransactions, previous.previousTransactions);
  const itemDelta = delta(actualItems, previous.previousItemQty);

  root.innerHTML = `
    <div class="planning-shell">
      <div class="planning-top">
        <div class="planning-title">
          <h1>Sales Planning Dashboard</h1>
          <p>${esc(model.companyName || "Company")} · Generated ${esc(model.generatedAt || "")} · ${esc(model.username || "")}</p>
        </div>

        <div class="planning-filters">
          <select id="branch-filter" ${model.canChangeBranch ? "" : "disabled"}>
            ${branchOptions(model.branches, model.selectedBranchId, model.canChangeBranch)}
          </select>
          <input id="date-from" type="date" value="${esc(model.dateFrom || "")}" />
          <input id="date-to" type="date" value="${esc(model.dateTo || "")}" />
          <button id="refresh-btn" class="btn-primary">Refresh</button>
          <button id="print-btn" class="btn-light">Print</button>
        </div>
      </div>

      <div class="kpi-grid">
        <div class="kpi-card">
          <div class="kpi-label">Actual sales</div>
          <div class="kpi-value">${money(actualSales)}</div>
          <div class="kpi-sub ${salesDelta.cls}">${salesDelta.text}</div>
        </div>

        <div class="kpi-card">
          <div class="kpi-label">Sales target</div>
          <div class="kpi-value">${money(salesTarget)}</div>
          <div class="kpi-sub">${money(n(salesTarget) - n(actualSales))} remaining</div>
        </div>

        <div class="kpi-card">
          <div class="kpi-label">Transactions</div>
          <div class="kpi-value">${qty(actualTransactions)}</div>
          <div class="kpi-sub ${txDelta.cls}">${txDelta.text}</div>
        </div>

        <div class="kpi-card">
          <div class="kpi-label">Items sold</div>
          <div class="kpi-value">${qty(actualItems)}</div>
          <div class="kpi-sub ${itemDelta.cls}">${itemDelta.text}</div>
        </div>
      </div>

      <div class="main-grid">
        <div class="panel">
          <h2>Daily Sales Trend</h2>
          <div class="chart-wrap">${chartSvg(trend)}</div>
          <div class="legend">
            <span class="actual">Actual sales</span>
            <span class="target">Target</span>
          </div>

          <table class="trend-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Target</th>
                <th>Actual</th>
                <th>Achievement</th>
              </tr>
            </thead>
            <tbody>
              ${trend.slice(-8).map(row => `
                <tr>
                  <td>${esc(row.label || row.targetDate || "")}</td>
                  <td>${money(row.salesTarget)}</td>
                  <td>${money(row.actualSales)}</td>
                  <td>${pct(row.salesAchievementPct || (n(row.salesTarget) ? n(row.actualSales) / n(row.salesTarget) * 100 : 0))}%</td>
                </tr>
              `).join("")}
            </tbody>
          </table>
        </div>

        <div class="panel">
          <h2>Target Achievement</h2>
          <div class="progress-card">
            <div class="ring" style="--pct:${Math.min(n(salesPct), 100)}%;">
              <div class="ring-inner">
                <div>
                  <strong>${pct(salesPct)}%</strong>
                  <div>of sales target</div>
                </div>
              </div>
            </div>
          </div>

          <div class="metric-list">
            <div class="metric-row">
              <span>Average basket</span>
              <strong>${money(avgBasket)}</strong>
            </div>
            <div class="metric-row">
              <span>Transaction target</span>
              <strong>${qty(transactionTarget)}</strong>
            </div>
            <div class="metric-row">
              <span>Item target</span>
              <strong>${qty(itemTarget)}</strong>
            </div>
            <div class="metric-row">
              <span>Previous sales</span>
              <strong>${money(previous.previousSales)}</strong>
            </div>
          </div>
        </div>
      </div>

      ${branchPerformancePanel(model.branchPerformance || [])}
    </div>
  `;

  document.getElementById("refresh-btn").onclick = () => {
    appsmith.updateModel({
      selectedBranchId: document.getElementById("branch-filter").value,
      dateFrom: document.getElementById("date-from").value,
      dateTo: document.getElementById("date-to").value
    });

    appsmith.triggerEvent("filtersChanged");
  };

  document.getElementById("print-btn").onclick = () => window.print();
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
